{
  "name": "estimate_cash_flow_exposure_workflow",
  "kind": "workflow",
  "description": "Parses bank, customer and supplier ledgers, reconciles them, and estimates a target month's cash-flow exposure with explicit assumptions, flagging overdue receivables.",
  "signature": {
    "in": "{\"type\":\"object\",\"properties\":{\"folder\":{\"type\":\"string\"},\"as_of_date\":{\"type\":\"string\"},\"target_month\":{\"type\":\"string\"},\"focus\":{\"type\":\"string\"}},\"required\":[\"folder\"]}",
    "out": "output of s4"
  },
  "steps": [
    {
      "id": "s1",
      "uses": "parse_supplier_invoices",
      "foreach": null,
      "inputs": [
        {
          "param": "folder",
          "source": "$input.folder"
        }
      ]
    },
    {
      "id": "s2",
      "uses": "parse_bank_and_customer_ledgers",
      "foreach": null,
      "inputs": [
        {
          "param": "folder",
          "source": "$input.folder"
        }
      ]
    },
    {
      "id": "s3",
      "uses": "reconcile_invoices_orders_bank",
      "foreach": null,
      "inputs": [
        {
          "param": "folder",
          "source": "$input.folder"
        },
        {
          "param": "invoices",
          "source": "$steps.s1.invoices"
        },
        {
          "param": "checks",
          "source": "[\"duplicate\",\"double_payment\",\"no_order\"]"
        }
      ]
    },
    {
      "id": "s4",
      "uses": "estimate_cash_flow_exposure",
      "foreach": null,
      "inputs": [
        {
          "param": "supplier_invoices",
          "source": "$steps.s1.invoices"
        },
        {
          "param": "bank_transactions",
          "source": "$steps.s2.bank_transactions"
        },
        {
          "param": "customer_invoices",
          "source": "$steps.s2.customer_invoices"
        },
        {
          "param": "as_of_date",
          "source": "$input.as_of_date"
        },
        {
          "param": "target_month",
          "source": "$input.target_month"
        },
        {
          "param": "focus",
          "source": "$input.focus"
        }
      ]
    }
  ],
  "output_step": "s4",
  "permissions": {
    "net": [],
    "llm": false
  },
  "budget": {
    "max_tokens_per_run": 0
  },
  "lineage": {
    "created_by": "factory",
    "uses": [
      "parse_supplier_invoices@v1",
      "parse_bank_and_customer_ledgers@v1",
      "reconcile_invoices_orders_bank@v2",
      "estimate_cash_flow_exposure@v4"
    ]
  },
  "example_input": "{\"folder\":\"novak_trading\",\"as_of_date\":\"2026-10-09\",\"target_month\":\"2026-11\",\"focus\":\"net cash-flow exposure and overdue receivables\"}",
  "purpose": "a bot that estimates next month's cash-flow exposure from our bank statement, supplier invoices and customer invoices, and flags overdue receivables\n\nFiles: folder novak_trading",
  "version": 2,
  "build_usd": 0.331,
  "build_seconds": 188,
  "headline": "For {input.target_month}, the expected net cash-flow exposure is {net_exposure_estimate}, starting from an opening balance of {opening_balance}, and the largest overdue receivable is {overdue_receivables.0.invoice_number} from {overdue_receivables.0.customer} for {overdue_receivables.0.amount}, whic",
  "examples": [
    "What will our cash flow look like next month?",
    "Which customers have overdue invoices and how much do they owe?",
    "What supplier payments do we need to cover in November?"
  ],
  "manual_minutes": 90.0,
  "manual_basis": "Reconcile the bank statement against supplier and customer invoices, work out typical payment lags, list overdue and upcoming items, and total expected inflows and outflows for the month.",
  "voice": "golem"
}

